      tx.set(doc(creditMovesCol),{customerId:customer.id,customerName:customerData.name,type:'debt',amount:orderRemaining,creditUsed,previousBalance:existingDebt,resultingBalance:finalDebt,previousCreditBalance:availableCredit,resultingCreditBalance:finalCredit,operationDate:fresh.businessDate||businessDate,note:`${fresh.title} Adisyon borcu`,source:'pos',saleId:saleRef.id,createdAt:serverTimestamp(),createdBy:auth.currentUser.uid});
      if(requestedPayment>0)tx.set(doc(creditMovesCol),{customerId:customer.id,customerName:customerData.name,type:paymentType==='transfer'?'transfer':'payment',amount:requestedPayment,previousBalance:existingDebt+orderRemaining,resultingBalance:finalDebt,previousCreditBalance:availableCredit,resultingCreditBalance:finalCredit,operationDate:fresh.businessDate||businessDate,note:`${fresh.title} müşteri hesabı ödemesi`,source:'pos',saleId:saleRef.id,createdAt:serverTimestamp(),createdBy:auth.currentUser.uid});
      for(const d of deductions){
        const current=Number(d.snap.data()?.quantity)||0,next=current-d.qty;
        tx.update(d.ref,{quantity:next,updatedAt:serverTimestamp()});
        tx.set(doc(stockMovesCol),{stockItemId:d.stock.id,stockName:d.stock.name,type:'out',amount:d.qty,previousQuantity:current,resultingQuantity:next,unit:d.stock.unit,operationDate:fresh.businessDate||businessDate,note:`Adisyon ${fresh.title}`,source:'pos',saleId:saleRef.id,createdAt:serverTimestamp(),createdBy:auth.currentUser.uid});
      }
      tx.set(saleRef,{recordType:'sale',settlementType:'credit',orderId:fresh.id,title:fresh.title,slotKey:fresh.slotKey,customerId:customer.id,customerName:customerData.name,items:fresh.items,subtotal:fresh.items.reduce((s,i)=>s+i.unitPrice*i.quantity,0),complimentaryTotal:fresh.items.filter(i=>i.complimentary).reduce((s,i)=>s+i.unitPrice*i.quantity,0),baseTotal:fullTotal,paymentAmount:requestedPayment,cashAmount:paymentType==='cash'?requestedPayment:0,transferAmount:paymentType==='transfer'?requestedPayment:0,creditBalanceUsed:creditUsed,openAccountAmount:Math.max(0,finalDebt-existingDebt),tipAmount:0,paymentType,businessDate:fresh.businessDate||businessDate,closedAt:serverTimestamp(),createdBy:auth.currentUser.uid});
