async function closeBusinessDay(){if(!currentCloseReport||orders.length||closingDayBusy||!el.closeDayConfirmed.checked)return;const closingDate=businessDate,closingRef=doc(closingsCol,`${closingDate}-${businessDayStartedAtMs}`),next=nextDate(closingDate),closedAtMs=Date.now();closingDayBusy=true;el.confirmCloseDay.disabled=true;el.confirmCloseDay.textContent='Kapatılıyor…';try{await runTransaction(db,async tx=>{const existing=await tx.get(closingRef);if(existing.exists())throw new Error('already-closed');tx.set(closingRef,{...currentCloseReport,closedAtMs,closedAt:serverTimestamp(),closedBy:auth.currentUser.uid,nextBusinessDate:next});tx.set(settingsRef,{lastClosedDate:closingDate,currentBusinessDate:next,currentBusinessDayStartedAtMs:closedAtMs,updatedAt:serverTimestamp()},{merge:true})});el.closeDayDialog.close();businessDate=next;businessDayStartedAtMs=closedAtMs;show(`Gün kapatıldı. Yeni iş günü: ${formatDate(next)}`)}catch(error){console.error(error);show(error.message==='already-closed'?'Bu iş günü daha önce kapatılmış.':'Gün kapatılamadı. Bağlantıyı ve kuralları kontrol edin.')}finally{closingDayBusy=false;el.confirmCloseDay.textContent='Günü Kesin Olarak Kapat';el.confirmCloseDay.disabled=!el.closeDayConfirmed.checked}}
function exportCloseDayPdf(){if(!currentCloseReport)return;const c=currentCloseReport,rows=c.products.map((p,i)=>`<tr><td>${i+1}</td><td>${esc(p.name)}</td><td>${p.quantity}</td><td>${money(p.unitPrice)}</td><td>${money(p.total)}</td></tr>`).join(''),body=`<table><thead><tr><th>No</th><th>Ürün</th><th>Adet</th><th>Birim Fiyat</th><th>Toplam</th></tr></thead><tbody>${rows}</tbody></table>`;openCorporatePdf(`${formatDate(c.businessDate)} Gün Sonu Raporu`,body,[["Esnaf Marka Satışı",`${c.merchantMarkaCount} Marka • ${money(c.merchantTopupTotal)}`],["Esnafa Teslim Çay",`${c.merchantDeliveredTea} Çay`],["Demlenen Çay",`${c.brewedPotCount} Demlik`],["Nakit Kasa",money(c.cashTotal)],["Banka Havalesi",money(c.transferTotal)],["Açık Hesap",money(c.openAccountTotal)],["Bahşiş",money(c.tipTotal)],["Hesap Yuvarlama",money(c.roundingTotal)],["Toplam Satış",money(c.salesTotal)]])}
function exportCloseDayExcel(){if(!currentCloseReport)return;const rows=currentCloseReport.products.map(p=>`<Row><Cell><Data ss:Type="String">${xml(p.name)}</Data></Cell><Cell><Data ss:Type="Number">${p.quantity}</Data></Cell><Cell><Data ss:Type="Number">${p.unitPrice}</Data></Cell><Cell><Data ss:Type="Number">${p.total}</Data></Cell></Row>`).join('');const content=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="Gün Sonu"><Table><Row><Cell><Data ss:Type="String">Ürün</Data></Cell><Cell><Data ss:Type="String">Adet</Data></Cell><Cell><Data ss:Type="String">Birim Fiyat</Data></Cell><Cell><Data ss:Type="String">Toplam</Data></Cell></Row>${rows}<Row><Cell><Data ss:Type="String">Demlenen Çay (Demlik)</Data></Cell><Cell/><Cell/><Cell><Data ss:Type="Number">${currentCloseReport.brewedPotCount}</Data></Cell></Row><Row><Cell><Data ss:Type="String">Toplam Satış</Data></Cell><Cell/><Cell/><Cell><Data ss:Type="Number">${currentCloseReport.salesTotal}</Data></Cell></Row><Row><Cell><Data ss:Type="String">Nakit Kasa</Data></Cell><Cell/><Cell/><Cell><Data ss:Type="Number">${currentCloseReport.cashTotal}</Data></Cell></Row><Row><Cell><Data ss:Type="String">Banka Havalesi</Data></Cell><Cell/><Cell/><Cell><Data ss:Type="Number">${currentCloseReport.transferTotal}</Data></Cell></Row><Row><Cell><Data ss:Type="String">Açık Hesap Bakiyesi</Data></Cell><Cell/><Cell/><Cell><Data ss:Type="Number">${currentCloseReport.openAccountTotal}</Data></Cell></Row><Row><Cell><Data ss:Type="String">Bahşiş</Data></Cell><Cell/><Cell/><Cell><Data ss:Type="Number">${currentCloseReport.tipTotal}</Data></Cell></Row><Row><Cell><Data ss:Type="String">Hesap Yuvarlama</Data></Cell><Cell/><Cell/><Cell><Data ss:Type="Number">${-currentCloseReport.roundingTotal}</Data></Cell></Row></Table></Worksheet></Workbook>`;downloadBlob(content,`gun-sonu-${currentCloseReport.businessDate}.xls`,'application/vnd.ms-excel')}
function openMove(){const current=orderFor(selectedKey);if(!current)return;const options=[];for(let i=1;i<=tableCount;i++){const key=`table-${i}`;if(key!==selectedKey)options.push({key,title:`Masa ${i}`,busy:!!orderFor(key)})}orders.filter(o=>o.slotType==='named'&&o.slotKey!==selectedKey).forEach(o=>options.push({key:o.slotKey,title:o.title,busy:true}));el.moveTarget.innerHTML='<option value="">Hedef seçin</option>'+options.map(x=>`<option value="${esc(x.key)}">${esc(x.title)}${x.busy?' — Birleştir':' — Taşı'}</option>`).join('');el.moveDialog.showModal()}
async function moveOrder(e){e.preventDefault();const source=orderFor(selectedKey),targetKey=el.moveTarget.value;if(!source||!targetKey)return;const target=orderFor(targetKey);try{await runTransaction(db,async tx=>{const sourceRef=doc(ordersCol,source.id),sourceSnap=await tx.get(sourceRef);if(!sourceSnap.exists())throw new Error('missing');const sourceData=sourceSnap.data();if(target){const targetRef=doc(ordersCol,target.id),targetSnap=await tx.get(targetRef);if(!targetSnap.exists())throw new Error('missing');const targetData=targetSnap.data();tx.update(targetRef,{items:mergeItems(targetData.items||[],sourceData.items||[]),payments:[...(targetData.payments||[]),...(sourceData.payments||[])],customTitle:targetData.customTitle||sourceData.customTitle||'',title:targetData.customTitle||sourceData.customTitle||targetData.title||baseSlotTitle(targetKey),creditCustomerId:targetData.creditCustomerId||sourceData.creditCustomerId||'',updatedAt:serverTimestamp()});tx.delete(sourceRef)}else tx.update(sourceRef,{slotKey:targetKey,slotType:'table',title:sourceData.customTitle||baseSlotTitle(targetKey),updatedAt:serverTimestamp()})});selectedKey=targetKey;el.moveDialog.close();show(target?'Adisyonlar birleştirildi; isim ve müşteri bağlantısı korundu.':'Adisyon, ismi ve müşteri bağlantısıyla taşındı.')}catch(err){console.error(err);show('Taşıma İşlemi tamamlanamadı.')}}
function mergeItems(a,b){return[...a,...b].map((item,index)=>({...item,lineId:item.lineId||`${newId()}-${index}`}))}
function cancelOrder(){const o=orderFor(selectedKey);if(!o)return;const paid=orderPaid(o);el.cancelMessage.textContent=`${slotTitle(selectedKey)} Adisyonu iptal edilecek. Satış ve stok kaydı oluşturulmayacak.${paid?` Daha önce alınan ${money(paid)} Nakit günün kasa kaydında kalacak.`:''}`;el.cancelDialog.showModal()}
async function confirmCancelOrder(){const o=orderFor(selectedKey);if(!o)return;try{await deleteDoc(doc(ordersCol,o.id));el.cancelDialog.close();showTables();show('Adisyon iptal edildi.')}catch(error){console.error(error);show('Adisyon iptal edilemedi.')}}
function itemsBill(items){return(items||[]).filter(i=>!i.complimentary).reduce((s,i)=>s+(Number(i.unitPrice)||0)*(Number(i.quantity)||0),0)}function billTotal(o){return itemsBill(o?.items||[])}function orderPaid(o){return(o?.payments||[]).reduce((s,p)=>s+(Number(p.amount)||0),0)}function orderTotal(o){return Math.max(0,billTotal(o)-orderPaid(o))}
function getBrewBusinessDate(brew){return brew?.businessDate||todayFromMs(Number(brew?.startedAtMs)||0)}
function todayFromMs(value){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul'}).format(new Date(value))}
function startOfBusinessDateMs(value){return new Date(`${value}T00:00:00+03:00`).getTime()}
function formatDateTime(value){return new Intl.DateTimeFormat('tr-TR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Europe/Istanbul'}).format(new Date(value))}
function formatTimeFromTimestamp(value){const date=value?.toDate?.();return date?new Intl.DateTimeFormat('tr-TR',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Europe/Istanbul'}).format(date):'Şimdi'}
function formatInputAmount(value){return Number.isInteger(Number(value))?String(Number(value)||0):Number(value||0).toFixed(2)}
function money(v){return new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',minimumFractionDigits:Number(v)%1?2:0}).format(Number(v)||0)}function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul'}).format(new Date())}function nextDate(value){const d=new Date(`${value}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+1);return d.toISOString().slice(0,10)}function formatDate(value){const [y,m,d]=String(value).split('-');return `${d}.${m}.${y}`}function newId(){return crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`}function formatOpened(value){const date=value?.toDate?.();return date?new Intl.DateTimeFormat('tr-TR',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Europe/Istanbul'}).format(date):'Şimdi'}function downloadBlob(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function xml(v){return String(v??'').replace(/[<>&'"]/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;',"'":'&apos;','"':'&quot;'}[c]))}function updateClock(){const n=new Date();$('currentTime').textContent=new Intl.DateTimeFormat('tr-TR',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Europe/Istanbul'}).format(n);$('currentDate').textContent=new Intl.DateTimeFormat('tr-TR',{day:'2-digit',month:'2-digit',year:'2-digit',timeZone:'Europe/Istanbul'}).format(n).replace(/\./g,'/')}function show(m){clearTimeout(toastTimer);el.toast.textContent=m;el.toast.classList.add('show');toastTimer=setTimeout(()=>el.toast.classList.remove('show'),3000)}function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function openCorporatePdf(title,body,totals){const popup=window.open('','_blank','width=1000,height=760');if(!popup)return show('PDF penceresi açılamadı.');const logo=new URL('../logo.png',location.href).href,created=new Intl.DateTimeFormat('tr-TR',{dateStyle:'full',timeStyle:'short',timeZone:'Europe/Istanbul'}).format(new Date());popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(title)}</title><style>@page{size:A4;margin:15mm}*{box-sizing:border-box}body{margin:0;color:#342522;font:12px Arial,sans-serif}.watermark{position:fixed;inset:20% 15%;width:70%;height:60%;object-fit:contain;opacity:.045;z-index:-1}.head{display:flex;justify-content:space-between;gap:20px;border-bottom:3px solid #7d1b24;padding-bottom:12px}.brand img{width:90px}.brand p{margin:2px 0}.date{text-align:right}.title{text-align:center;color:#7d1b24;margin:22px 0 14px}table{width:100%;border-collapse:collapse}thead{display:table-header-group}th{background:#7d1b24;color:#fff}th,td{padding:9px;border:1px solid #d8c6ba;text-align:left}tbody tr:nth-child(even){background:#fff7ef}.totals{width:50%;margin:16px 0 0 auto;border:1px solid #d8c6ba}.totals div{display:flex;justify-content:space-between;padding:8px;border-bottom:1px solid #eaded6}.totals div:last-child{border:0;background:#fff2e2;color:#7d1b24;font-weight:bold}</style></head><body><img class="watermark" src="${logo}"><header class="head"><div class="brand"><img src="${logo}"><p><b>Fatih Ali Altınlı</b></p><p>0554 118 08 06</p><p>Ulukavak Mah. Osmancık Cad. No:285<br>Çorum/Merkez</p></div><div class="date"><b>Oluşturma Tarihi</b><p>${created}</p></div></header><h1 class="title">${esc(title)}</h1>${body}<section class="totals">${totals.map(x=>`<div><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</section><script>window.onload=()=>setTimeout(()=>window.print(),350)<\/script></body></html>`);popup.document.close()}
